def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_my = my[-1]
    last_opp = opp[-1]

    opp_c = 0
    for b in opp:
        if b == 'C':
            opp_c += 1
    opp_d = n - opp_c
    rate = opp_c / float(n)

    if n >= 5:
        rate5 = opp[-5:].count('C') / 5.0
    else:
        rate5 = rate

    if n >= 10:
        rate10 = opp[-10:].count('C') / 10.0
    else:
        rate10 = rate

    if n >= 20:
        rate20 = opp[-20:].count('C') / 20.0
    else:
        rate20 = rate

    afterD_t = 0
    afterD_c = 0
    afterC_t = 0
    afterC_c = 0
    start = n - 30
    if start < 1:
        start = 1
    for i in range(start, n):
        if my[i - 1] == 'D':
            afterD_t += 1
            if opp[i] == 'C':
                afterD_c += 1
        else:
            afterC_t += 1
            if opp[i] == 'C':
                afterC_c += 1

    if afterD_t > 0:
        afterD_rate = afterD_c / float(afterD_t)
    else:
        afterD_rate = 0.5

    if afterC_t > 0:
        afterC_rate = afterC_c / float(afterC_t)
    else:
        afterC_rate = 0.5

    responsiveness = afterC_rate - afterD_rate

    run_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            run_d += 1
        else:
            break

    period_fit = 0.0
    best_p = 1
    if n >= 16:
        start = n - 16
        if start < 0:
            start = 0
        window = opp[start:]
        L = len(window)
        for p in range(2, 6):
            if L >= 3 * p:
                tot = 0
                match = 0
                for i in range(p, L):
                    tot += 1
                    if window[i] == window[i - p]:
                        match += 1
                if tot > 0:
                    fit = match / float(tot)
                    if fit > period_fit:
                        period_fit = fit
                        best_p = p

    if n >= 22 and best_p >= 2 and period_fit >= 0.8:
        if afterD_t >= 4 and afterD_rate >= 0.55:
            if afterC_t < 2 or responsiveness < 0.35:
                return 'D'

    if afterD_t >= 2 and afterD_rate >= 0.8 and afterC_rate >= 0.6 and responsiveness < 0.15 and rate >= 0.7:
        return 'D'

    if afterD_t >= 3 and afterD_rate >= 0.7 and afterC_rate >= 0.45 and responsiveness < 0.3:
        return 'D'

    if last_my == 'D' and last_opp == 'C':
        if n >= 2 and my[-2] == 'D' and opp[-2] == 'C':
            if rate >= 0.45:
                return 'D'

        prev_run = 0
        if n >= 2:
            for i in range(n - 2, -1, -1):
                if opp[i] == 'D':
                    prev_run += 1
                else:
                    break
        if prev_run >= 4 and rate >= 0.35:
            return 'D'

        if opp_d == 0 and afterD_t >= 1 and afterD_rate >= 0.75:
            return 'D'

    if last_my == 'C' and last_opp == 'C':
        if opp_d == 0 and afterD_t >= 1 and afterD_rate >= 0.75:
            return 'D'

    if run_d == 5 and last_my == 'D' and opp_c >= n * 0.3:
        return 'C'

    if last_my == 'C' and last_opp == 'D':
        if n >= 2 and my[-2] == 'D' and opp[-2] == 'C':
            if rate >= 0.35:
                return 'C'
        return 'D'

    if last_my == 'D' and last_opp == 'C':
        return 'C'

    if last_my == 'D' and last_opp == 'D':
        if run_d >= 5 and rate < 0.4:
            return 'D'
        return 'D'

    if n >= 8:
        probe = 0.02
        if rate >= 0.9:
            probe = 0.06
            if afterD_t >= 1:
                if responsiveness > 0.45:
                    probe = 0.01
                elif responsiveness < 0.25:
                    probe = 0.12
        if rng.random() < probe:
            return 'D'

    return 'C'
